record.field:
website = env.ref('fitness.website_industry')
to_deactivate = [ 'website.header_search_box', 'website.header_text_element', 'website_event.opt_event_organizer_block', 'website_event.opt_event_share_block', 'website_sale.cta_separator', 'website_sale.product_terms_and_conditions', 'website_sale.products_attributes', 'website_sale.products_shop_title', 'website_sale.search', 'website_sale.sort', 'website_sale.product_add_to_wishlist', 'website_sale.product_add_to_compare', 'website.homepage', 'website.contactus', 'portal.user_sign_in', ] to_activate = [ 'website.footer_no_copyright', 'website.template_header_default_align_center', 'website_event.opt_event_description_cover_top', 'website_sale.header_hide_empty_cart_link', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)] top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1)
# Default menu items to remove menus.search(base_domain + [('url', 'in', ['/', '/event', '/appointment'])]).unlink() # Rename /shop menu to "Products" menus.search(base_domain + [('url', '=', '/shop')], limit=1).write({'name': 'Products', 'sequence': 2, 'is_visible': True}) # Add custom menu items menus.create([ { 'name': 'About', 'url': '/about-us', 'website_id': website.id, 'parent_id': top_menu.id, 'sequence': 1, 'is_visible': True, }, { 'name': 'Courses', 'url': '/courses', 'website_id': website.id, 'parent_id': top_menu.id, 'sequence': 3, 'is_visible': True, }, { 'name': 'Events', 'url': '/our-events', 'website_id': website.id, 'parent_id': top_menu.id, 'sequence': 4, 'is_visible': True, }, ])

website = env.ref('fitness.website_industry')
MARK = '__EXPORT_FILTER_XMLID__'
for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]):
    arch = view.arch_db or ''
    if MARK not in arch:
        continue
    new_arch = arch
    while MARK in new_arch:
        start = new_arch.index(MARK)
        end = new_arch.index(MARK, start + len(MARK)) + len(MARK)
        xmlid = new_arch[start + len(MARK):end - len(MARK)]
        try:
            resolved = str(env.ref(xmlid).id)
        except ValueError:
            resolved = '0'
        new_arch = new_arch[:start] + resolved + new_arch[end:]
    view.write({'arch_db': new_arch})
